
const express=require('express'),axios=require('axios'),{execFile}=require('child_process');const app=express();app.use(express.json({limit:'2mb'}));const GATEWAY=process.env.GATEWAY_URL||'http://gateway:8097';const tools={'controller.profile.save':async a=>(await axios.post(GATEWAY+'/profiles',a)).data,'controller.led.set':async a=>(await axios.post(GATEWAY+'/hardware/led',a)).data,'controller.telemetry.latest':async()=> (await axios.get(GATEWAY+'/health')).data,'swarm.service.list':async()=>new Promise(r=>execFile('docker',['service','ls','--format','json'],{timeout:5000},(e,out,err)=>r({ok:!e,out,err}))),'docker.ps':async()=>new Promise(r=>execFile('docker',['ps','--format','json'],{timeout:5000},(e,out,err)=>r({ok:!e,out,err})))};app.get('/health',(q,s)=>s.json({ok:true,tools:Object.keys(tools)}));app.post('/mcp',async(q,s)=>{const{id,method,params}=q.body||{};try{if(!tools[method])throw Error('unknown tool '+method);s.json({jsonrpc:'2.0',id,result:await tools[method](params||{})})}catch(e){s.json({jsonrpc:'2.0',id,error:{code:-32000,message:String(e.message||e)}})}});app.listen(8098,()=>console.log('xbox cosmic MCP listening on :8098'));
